import 'package:supabase_flutter/supabase_flutter.dart';
import '../config/app_config.dart'; import '../config/supabase_config.dart'; import '../models/notification.dart';
class NotificationRepository { SupabaseClient get c=>SupabaseConfig.client; Future<List<AppNotification>>get({int limit=50,DateTime?before})async{if(AppConfig.demoMode)return [];final r=await c.rpc('get_notifications',params:{'p_limit':limit,'p_before':before?.toIso8601String()});return (r as List).map((e)=>AppNotification.fromMap(e)).toList();} Future<void>read(String id)async{if(!AppConfig.demoMode)await c.rpc('mark_notification_read',params:{'p_id':id});} Future<void>readAll()async{if(!AppConfig.demoMode)await c.rpc('mark_all_notifications_read');}}
